def check_type(var):
    """Check the type of a variable and print out the result."""
    try:
        # Try to convert the variable to different types and check if it raises a TypeError
        int_result = int(var)
        float_result = float(var)
        str_result = str(var)

        if isinstance(int_result, int) and isinstance(float_result, float) and isinstance(str_result, str):
            return "Integer"
        elif isinstance(int_result, int):
            return "Integer"
        elif isinstance(float_result, float):
            return "Float"
        elif isinstance(str_result, str):
            return "String"
        else:
            return "Unknown"

    except TypeError:
        return "Unknown"

# Call the function with a sample input
sample_input = 10
print(check_type(sample_input))
```

